{"implementation":"import math


def solve(case):
    if not isinstance(case, dict):
        raise ValueError("case must be an object")
    if "nodes" not in case or "required_symbols" not in case:
        raise ValueError("missing required case fields")
    nodes = case["nodes"]
    required_symbols = case["required_symbols"]
    if not isinstance(nodes, list) or not nodes:
        raise ValueError("nodes must be a non-empty list")
    if not isinstance(required_symbols, list) or any(not isinstance(s, str) for s in required_symbols):
        raise ValueError("required_symbols must be a list of strings")

    required = set(required_symbols)
    by_id = {}
    source_ids = []
    for node in nodes:
        if not isinstance(node, dict):
            raise ValueError("each node must be an object")
        fields = ("id", "parent", "symbol", "depth", "removable", "utility")
        if any(field not in node for field in fields):
            raise ValueError("node is missing a required field")
        node_id = node["id"]
        if not isinstance(node_id, str) or node_id in by_id:
            raise ValueError("node ids must be unique strings")
        if not isinstance(node["symbol"], str):
            raise ValueError("node symbol must be a string")
        if not isinstance(node["depth"], int) or isinstance(node["depth"], bool) or node["depth"] < 0:
            raise ValueError("node depth must be a non-negative integer")
        if not isinstance(node["removable"], bool):
            raise ValueError("node removable must be boolean")
        utility = node["utility"]
        if not isinstance(utility, (int, float)) or isinstance(utility, bool) or not math.isfinite(utility):
            raise ValueError("node utility must be finite numeric")
        parent = node["parent"]
        if parent is not None and not isinstance(parent, str):
            raise ValueError("node parent must be null or a string")
        by_id[node_id] = node
        source_ids.append(node_id)

    roots = [node for node in nodes if node["parent"] is None]
    if len(roots) != 1 or roots[0]["depth"] != 0:
        raise ValueError("tree must have exactly one depth-zero root")
    root_id = roots[0]["id"]
    children = {node_id: [] for node_id in source_ids}
    for node in nodes:
        parent = node["parent"]
        if parent is not None:
            if parent not in by_id:
                raise ValueError("parent must reference an existing node")
            if node["depth"] != by_id[parent]["depth"] + 1:
                raise ValueError("node depth is inconsistent with its parent")
            children[parent].append(node["id"])

    seen = set()
    stack = [root_id]
    while stack:
        node_id = stack.pop()
        if node_id in seen:
            raise ValueError("tree contains a cycle or duplicate traversal")
        seen.add(node_id)
        stack.extend(children[node_id])
    if len(seen) != len(nodes):
        raise ValueError("tree must be connected")
    if not required.issubset({node["symbol"] for node in nodes}):
        raise ValueError("required symbols are not represented")

    retained = set(source_ids)
    removed = []
    candidates = sorted(nodes, key=lambda node: (-node["depth"], node["id"]))
    for node in candidates:
        node_id = node["id"]
        if node_id == root_id or not node["removable"] or node["symbol"] in required:
            continue
        if any(child_id in retained for child_id in children[node_id]):
            continue
        remaining_symbols = {by_id[kept_id]["symbol"] for kept_id in retained if kept_id != node_id}
        if required.issubset(remaining_symbols):
            retained.remove(node_id)
            removed.append(node_id)

    return {"removed_node_ids": removed, "retained_node_ids": sorted(retained)}"}
